public class Main {
    public static void main(String[] args) {
        // 산술 연산
        int a = 10;
        int b = 3;
        System.out.println(a / b); // 3 (몫)
        System.out.println(a % b); // 1 (나머지)

        // 논리 연산
        boolean isAdult = true;
        boolean hasMoney = false;

        // AND (둘 다 true여야 true)
        boolean canBuy = isAdult && hasMoney;

        // OR (하나만 true면 true)
        boolean canEnter = isAdult || hasMoney;
    }
}
